//! Generates `src/families.rs`, the library's view of the vendored assets.
//!
//! Keeping this generated rather than hand-written means [`SOURCES`] is the one
//! place a family is described: adding one is a matter of appending an entry
//! there and re-running this tool.

use crate::sources::{SOURCES, Source};

/// Render the family registry module.
pub fn render() -> String {
    let mut out = String::new();

    out.push_str(
        "// Generated by `cargo run -p vendor`. Do not edit manually.\n\
         //\n\
         //! The icon families compiled into this build.\n\
         //!\n\
         //! Each family is gated behind its Cargo feature, so a build only pays for\n\
         //! the fonts it asked for: a disabled family's assets are never embedded.\n\n\
         use crate::Family;\n\n",
    );

    for source in SOURCES {
        out.push_str(&render_family(source));
    }

    out.push_str(
        "/// Every family enabled by the current feature set, in declaration order.\n\
         // Each push is behind its own `cfg`, so they cannot be collapsed into the\n\
         // initialiser the way the lint suggests.\n\
         #[allow(clippy::vec_init_then_push)]\n\
         pub(crate) fn enabled() -> Vec<&'static Family> {\n\
         \x20   #[allow(unused_mut)]\n\
         \x20   let mut families: Vec<&'static Family> = Vec::new();\n\n",
    );

    for source in SOURCES {
        out.push_str(&format!(
            "    #[cfg(feature = \"{feature}\")]\n    families.push(&{constant});\n",
            feature = source.feature,
            constant = constant_name(source.id),
        ));
    }

    out.push_str("\n    families\n}\n");

    out
}

fn render_family(source: &Source) -> String {
    let mut out = String::new();

    out.push_str(&format!(
        "/// [{label}]({browse}) — {license}.\n",
        label = source.label,
        browse = source.browse_url,
        license = source.license,
    ));

    if let Some(note) = source.note {
        out.push_str("///\n");
        for line in wrap(note, 72) {
            out.push_str(&format!("/// {line}\n"));
        }
    }

    out.push_str(&format!(
        "#[cfg(feature = \"{feature}\")]\n\
         pub(crate) const {constant}: Family = Family {{\n\
         \x20   id: {id:?},\n\
         \x20   label: {label:?},\n\
         \x20   feature: {feature_name:?},\n\
         \x20   font_family: {font_family:?},\n\
         \x20   file_stem: {file_stem:?},\n\
         \x20   browse_url: {browse_url:?},\n\
         \x20   license: {license:?},\n\
         \x20   font: include_bytes!(\"../assets/{id}/{file_stem}.ttf\"),\n\
         \x20   index: include_str!(\"../assets/{id}/icons.idx\"),\n\
         }};\n\n",
        feature = source.feature,
        feature_name = source.feature,
        constant = constant_name(source.id),
        id = source.id,
        label = source.label,
        font_family = source.font_family,
        file_stem = source.file_stem,
        browse_url = source.browse_url,
        license = source.license,
    ));

    out
}

/// `fa-solid` becomes `FA_SOLID`.
fn constant_name(id: &str) -> String {
    id.replace('-', "_").to_uppercase()
}

/// Break a note into doc-comment-width lines.
fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = Vec::new();
    let mut current = String::new();

    for word in text.split_whitespace() {
        if !current.is_empty() && current.len() + 1 + word.len() > width {
            lines.push(std::mem::take(&mut current));
        }

        if !current.is_empty() {
            current.push(' ');
        }
        current.push_str(word);
    }

    if !current.is_empty() {
        lines.push(current);
    }

    lines
}
